from __future__ import annotations

import json
from typing import Any
from unittest.mock import patch

from reflex.vars import Var
from reflex.vars import function as function_mod
from reflex.vars.function import FunctionStringVar, VarOperationCall


def _type_summary(value: Any) -> str | None:
    if value is None:
        return None
    return getattr(value, "__name__", str(value))


def _optional_attr(value: Any, name: str):
    try:
        return object.__getattribute__(value, name)
    except AttributeError:
        return None


def _value_summary(value: Any):
    if isinstance(value, tuple):
        return [_value_summary(item) for item in value]
    if isinstance(value, Var):
        summary = {
            "__class__": type(value).__name__,
            "_js_expr": value._js_expr,
            "_var_type": _type_summary(value._var_type),
            "_var_data": None if value._var_data is None else str(value._var_data),
        }
        var_value = _optional_attr(value, "_var_value")
        if var_value is not None:
            summary["_var_value"] = var_value
        original = _optional_attr(value, "_original")
        if original is not None:
            summary["_original._js_expr"] = original._js_expr
            summary["_original.__class__"] = type(original).__name__
        return summary
    return value


class TestVarsFunctionPartialCallInputStateQA:
    def test_vars_function_partial_call_input_state_case(self):
        captured = {}
        original_create = VarOperationCall.create
        handler = FunctionStringVar.create("handler.process")
        count = Var(_js_expr="state.count + offset", _var_type=int)

        def capture_create(
            cls,
            func,
            *args,
            _var_type=Any,
            _var_data=None,
        ):
            captured.update(
                {
                    "func": _value_summary(func),
                    "args": _value_summary(args),
                    "_var_type": _type_summary(_var_type),
                    "_var_data": None if _var_data is None else str(_var_data),
                }
            )
            return original_create.__func__(
                cls,
                func,
                *args,
                _var_type=_var_type,
                _var_data=_var_data,
            )

        with patch.object(
            function_mod.VarOperationCall,
            "create",
            classmethod(capture_create),
        ):
            result = handler.partial("alpha", count)

        print("QA_RESULT_JSON=" + json.dumps(captured, sort_keys=True))

        assert str(result) == "((...args) => (handler.process(\"alpha\", state.count + offset, ...args)))"
        assert captured["args"][0] == "alpha"
        assert captured["args"][1]["_js_expr"] == "state.count + offset"
        assert captured["args"][2]["_js_expr"] == "...args"
